mapper.select:
SELECT * FROM (
    SELECT ROWNUM AS RN, T.* FROM (
        SELECT R.REVIEW_ID, R.PRODUCT_ID, R.REVIEWER_NO, R.REVIEWEE_NO,
               R.RATING, R.CONTENT, R.REG_DATE,
               COALESCE(MP.NICKNAME, U.NAME) AS REVIEWER_NAME,
               P.PRODUCT_TITLE
        FROM REVIEW R
        JOIN USERS U              ON R.REVIEWER_NO = U.USER_NO
        LEFT JOIN MY_USER_PAGE MP ON R.REVIEWER_NO = MP.USER_NO
        JOIN PRODUCT P            ON R.PRODUCT_ID  = P.PRODUCT_ID
        WHERE R.REVIEWEE_NO = #{revieweeNo}
        ORDER BY R.REG_DATE DESC
    ) T
    WHERE ROWNUM <= #{endRow}
)
WHERE RN > #{startRow}
